import{z as E,x as B,o as t,c as p,q as r,j as o,D as e,d as i,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"视觉 token 压缩","description":"","frontmatter":{"title":"视觉 token 压缩","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vision-token-compression.md","filePath":"llm/vision-token-compression.md","lastUpdated":1791063341000}'),m={name:"llm/vision-token-compression.md"};function A(h,a,d,c,_,f){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="视觉-token-压缩" tabindex="-1">视觉 token 压缩 <a class="header-anchor" href="#视觉-token-压缩" aria-label="Permalink to &quot;视觉 token 压缩&quot;">​</a></h1><div class="epigraph"><p>高分辨率把字看清了，也把语言模型的窗口塞满了；压缩要删的是空间冗余，不是把文档理解所需的格子一并抹掉。</p><footer>—— 对照 LLaVA 直连、Qwen-VL 查询与 InternVL 像素 shuffle</footer></div><p><a href="/llm/anyres">AnyRes</a> 与更高清的 ViT 输入让视觉前缀从数百涨到数千 token。LLM 的注意力仍是序列长度二次，decode 的 KV 也按视觉前缀长度线性涨。视觉 token 压缩的目标是：在进语言模型之前（或刚进去时）把 \\(N_{\\mathrm{vis}}\\) 降下来，同时尽量保住布局与细字。它和文本侧的 <a href="/llm/kv-as-long-context">KV 压缩</a> 同属预算问题，但删的是二维格子上的冗余，不是生成过程中的过去词。本篇对照查询瓶颈、规则下采样与池化，Qwen2-VL 的 \\(2\\times 2\\) merge 训练细节留给下一篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">576 这个数可以自己算：\\(336 \\div 14 = 24\\)，即每边 24 个 patch，\\(24 \\times 24 = 576\\)。若做一次 \\(2\\times 2\\) 合并，就只剩 \\(12 \\times 12 = 144\\) 个——压缩 4 倍，代价是每个向量塞进了原来 4 个格子的内容。</span></p><p>一张 336 边长、\\(P=14\\) 的图约 576 个视觉 token；2×2 AnyRes 加上全局视图可以到两千以上；多页文档再乘页数。对话模型还要留系统提示、多轮文本。若不压缩，高分辨率与长对话互斥。若压缩太狠，<a href="/llm/ocr-vlm">OCR</a> 与小物体检测先崩：被合并的格子里塞进了多个字符，语言模型再强也解不开混叠。</p><p>问题于是有约束：压缩比可调；尽量保持二维拓扑（读序、表结构）；最好不引入与 LLM 核不一致的不规则 gather。内容自适应压缩上限更高，也更难训、更难复现。规则 \\(2\\times 2\\) 最稳，压缩比钉死。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="查询瓶颈" tabindex="-1">查询瓶颈 <a class="header-anchor" href="#查询瓶颈" aria-label="Permalink to &quot;查询瓶颈&quot;">​</a></h3><p>Q-Former 与 <a href="/llm/vl-connector">Qwen-VL 适配器</a> 用 \\(M\\) 个可学习查询交叉注意全部 patch，输出长度恒为 \\(M\\)。压缩比 \\(N_{\\mathrm{vis}}/M\\) 随分辨率自动变大：图越大，每个查询要覆盖的面积越大。这适合「视觉前缀必须钉死」的服务配额。信息选择是内容相关的，查询可以学会盯标题；也可以学会偷懒只看中心物体，把边缘小字丢掉。</p><h3 id="规则空间合并" tabindex="-1">规则空间合并 <a class="header-anchor" href="#规则空间合并" aria-label="Permalink to &quot;规则空间合并&quot;">​</a></h3><p><span class="marginnote">「像素 shuffle」就是把空间格子搬到通道维度：四个相邻小格并排拼成一个宽向量，格子数变四分之一，每个向量变四倍宽。类比把 \\(2\\times 2\\) 的四张便签誊到一张更宽的纸上——信息都在，但原来「一格一字」的边界没有了。</span></p><p>像素 shuffle / \\(2\\times 2\\) 合并把邻接四块拼成一个更宽向量，再投影。长度降为约 \\(1/4\\)，格子仍是图。没有离散选择，训练稳定，和卷积里的空间–通道重排同构。可以叠两次得到 16×，但混叠按幂加重。平均池化或步盘卷积是更糊的同类：同样降网格，通道不增，信息更易丢。LLaVA 式 MLP 直连则相当于压缩比为 1，长度问题原样交给 LLM。</p> \\[N_{\\mathrm{out}}\\approx\\frac{H}{P\\cdot r}\\cdot\\frac{W}{P\\cdot r} \\]<p>\\(r=2\\) 即一次 \\(2\\times 2\\)。\\(r\\) 与输入分辨率联合决定 OCR 粒度：先升分辨率再 \\(r=2\\)，往往优于低分辨率直连。</p>',15)),(t(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%AB%98%E6%B8%85%20patch%20%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20B%5B%22%E6%9F%A5%E8%AF%A2%E5%8E%8B%E7%BC%A9%E5%88%B0%20M%22%5D%0A%20%20A%20--%3E%20C%5B%22%E8%A7%84%E5%88%99%202%20%E4%B9%98%202%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%B1%A0%E5%8C%96%E6%88%96%E6%AD%A5%E7%9B%98%22%5D%0A%20%20B%20--%3E%20E%5B%22%E5%9B%BA%E5%AE%9A%E9%95%BF%E5%BA%A6%E5%89%8D%E7%BC%80%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%9B%9B%E5%88%86%E4%B9%8B%E4%B8%80%E6%A0%BC%E5%AD%90%22%5D%0A%20%20D%20--%3E%20F%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="和文本-kv-压缩不是同一刀" tabindex="-1">和文本 KV 压缩不是同一刀 <a class="header-anchor" href="#和文本-kv-压缩不是同一刀" aria-label="Permalink to &quot;和文本 KV 压缩不是同一刀&quot;">​</a></h3><p>H2O、SnapKV 删的是时间上的过去 token；视觉压缩删的是空间上的邻域。视觉前缀通常一次性进 prefill，之后作为静态键被所有生成步读取，所以更像「prompt 侧的 SnapKV」，但栅格结构允许用确定性 merge，而不必依赖观察窗注意力。对视觉前缀再做文本式驱逐（按注意力分数扔 patch）是可行的实验，却容易把唯一的那个字扔掉；文档任务上优先规则合并或查询，而不是生成中途再丢格子。</p><p><span class="marginnote">压缩发生在连接器，还是发生在 LLM 的 KV 里，服务形态不同。前者缩短 prefill 序列，KV 从一开始就短；后者先算满视觉注意力再量化/驱逐。文档 VLM 应尽量在进 LLM 前压完，避免为已经混叠的 token 再付二次注意力。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>规则合并假设局部四块统计上冗余：自然图像的纹理、大色块背景确实如此。文字图像相反：相邻 patch 往往是不同字符，合并等于人为制造「两字合一」的视觉词，语言模型只能靠上下文猜。因此同一 \\(r=2\\)，在照片字幕上几乎无感，在扫描件上掉字。查询瓶颈的机制是软选择：容量 \\(M\\) 的槽位，梯度会把它们推向训练集里最能降损失的区域——若数据以自然图为主，槽位不会自动去盯页脚页码。</p><p><span class="marginnote">评测压缩必须按任务拆开。只报综合 VQA 平均值，会被自然图稀释。应单独报：小字 OCR、表格格点、多物体计数。这三项对 \\(N_{\\mathrm{vis}}\\) 最敏感。</span></p><p>规则合并的一次 \\(2\\times 2\\) 具体长这样，以及它为何在文字图上出问题：</p>',7)),(t(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9B%B8%E9%82%BB%E5%9B%9B%E4%B8%AA%20patch%22%5D%20--%3E%20B%5B%22%E5%B7%A6%E4%B8%8A%20%2B%20%E5%8F%B3%E4%B8%8A%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%B7%A6%E4%B8%8B%20%2B%20%E5%8F%B3%E4%B8%8B%22%5D%0A%20%20B%20--%3E%20D%5B%22%E6%8B%BC%E6%88%90%E5%AE%BD%E5%90%91%E9%87%8F%204C%20%E7%BB%B4%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E7%BA%BF%E6%80%A7%E6%8A%95%E5%BD%B1%E5%9B%9E%20LLM%20%E7%BB%B4%E5%BA%A6%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%87%AA%E7%84%B6%E5%9B%BE%EF%BC%9A%E7%BA%B9%E7%90%86%E5%86%97%E4%BD%99%EF%BC%8C%E5%87%A0%E4%B9%8E%E6%97%A0%E6%8D%9F%22%5D%0A%20%20E%20--%3E%20G%5B%22%E6%89%AB%E6%8F%8F%E4%BB%B6%EF%BC%9A%E4%B8%A4%E5%AD%97%E6%B7%B7%E5%8F%A0%E6%88%90%E4%B8%80%E4%BD%93%EF%BC%8C%E6%8E%89%E5%AD%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">初学者容易以为压缩比越高越省越好。实际上叠到 \\(16\\times\\) 时，一个输出格子要装下 256 个原 patch 的内容，扫描件上的小字基本必糊。压缩比要和「任务最小可读字号」一起定，而不是当成免费的长度旋钮。</span></p><p>长度降下来之后，LLM 的 softmax 分母更短，每个视觉键的权重更大，这有时反而改善「图被长问题淹没」。压缩不是单向损质量，它也在重新校准跨模态注意力。前提是留下的键仍对应任务所需的空间尺度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有对所有任务最优的压缩比。端侧聊天可以 \\(M=64\\) 或两次 shuffle；文档解析应提高输入分辨率，只做一次 \\(2\\times 2\\)，甚至直连再配合窗口注意力。多图、视频会把 \\(N_{\\mathrm{vis}}\\) 再乘时间或张数，必须有总预算，否则单张图的精心切格会在第二张图上被截断。</p><p>不要把视觉压缩写成「免费的 AnyRes」。升分辨率再压回原来的 token 数，中间仍有混叠，只是混叠发生在更细的原图像素上——这对中等字号有效，对更小的字仍要继续加格。也不要把 Qwen2-VL 的 merge 与 InternVL 的 shuffle 当成算法论文里的不同发明来夸大：工程上都是 \\(2\\times 2\\) 空间重排加线性，差别在是否与原生可变分辨率、窗口注意力一起训。</p><p><span class="marginnote">服务日志里若视觉 token 数随用户上传的像素线性涨、没有上限，压缩策略等于没落地。应在预处理就设定最小/最大像素或最大 \\(N_{\\mathrm{vis}}\\)，过大则先缩小，过小则上采样，避免极端长度打爆 KV。</span></p><p>取舍顺序：先定任务最小可读字号，反推 \\(P\\) 与输入边长；再选 \\(r\\) 或 \\(M\\) 把 \\(N_{\\mathrm{out}}\\) 落入 LLM 窗口；最后才考虑对视觉 KV 做量化。倒过来先压长度，再抱怨 OCR 差，是预算写错了轴。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉 token 压缩把高分辨率带来的 \\(N_{\\mathrm{vis}}\\) 降到 LLM 窗口可承受的范围。</li><li>查询瓶颈钉死长度、内容选择不可逆；规则 \\(2\\times 2\\) 保拓扑、压缩比固定；直连不压缩。</li><li>自然图纹理冗余高，文档文字冗余低，同一压缩比不可混用验收。</li><li>压缩应尽量发生在进 LLM 之前，使 prefill 与 KV 一起变短。</li><li>升分辨率再合并，对中等字号优于低分辨率直连，但不能替代真正的细格子。</li><li>必须设 \\(N_{\\mathrm{vis}}\\) 上限；与文本 KV 驱逐是不同轴。</li><li>出处：对照 Liu et al., LLaVA, 2023；Bai et al., Qwen-VL, 2023；Chen et al., InternVL, 2023/2024；Wang et al., Qwen2-VL, 2024（merge 细节见后续专文）。AnyRes 见 LLaVA-NeXT。</li></ul>',9))])}const V=E(m,[["render",A]]);export{u as __pageData,V as default};
